<?php
require dirname(__DIR__).'/bootstrap.php';
use AranduGo\Auth;use AranduGo\Database;use AranduGo\SiteRepository;use AranduGo\Support;
Auth::requireLogin();if(!class_exists('ZipArchive'))exit('La extensión ZIP de PHP no está habilitada.');$file=Support::basePath('storage/backups/arandu-go-'.date('Ymd-His').'.zip');$zip=new ZipArchive();if($zip->open($file,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)exit('No se pudo crear el respaldo.');$zip->addFromString('contenido/draft.json',json_encode(SiteRepository::draft(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$zip->addFromString('contenido/published.json',json_encode(SiteRepository::published(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));foreach(['users','site_profiles','contact_messages','password_resets','migrations','update_history'] as $table){try{$rows=Database::connection()->query('SELECT * FROM '.Database::table($table))->fetchAll();$zip->addFromString('database/'.$table.'.json',json_encode($rows,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}catch(Throwable){}}if(is_file(Support::basePath('config/config.php')))$zip->addFile(Support::basePath('config/config.php'),'protegido/config.php');$root=Support::basePath('uploads');if(is_dir($root)){$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($iterator as $item){if(!$item->isFile()||str_starts_with($item->getFilename(),'.'))continue;$relative='uploads/'.substr($item->getPathname(),strlen($root)+1);$zip->addFile($item->getPathname(),$relative);}}$zip->close();header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.basename($file).'"');header('Content-Length: '.filesize($file));readfile($file);unlink($file);exit;
